import React, { useState, useEffect } from 'react';
import { useNavigate } from 'react-router-dom';
import Calendar from 'react-calendar';
import 'react-calendar/dist/Calendar.css';

const API_BASE_URL = window.location.hostname === 'localhost'
    ? 'http://localhost:3001'
    : 'https://requena-backend-production.up.railway.app';

const EmployeeDashboard = () => {
  const navigate = useNavigate();
  const [user, setUser] = useState(null);
  const [vacationDays, setVacationDays] = useState(0);
  const [hasCheckedIn, setHasCheckedIn] = useState(false);
  const [hasCheckedOut, setHasCheckedOut] = useState(false);
  const [loading, setLoading] = useState(false);
  const [selectedDates, setSelectedDates] = useState([]);
  const [showCalendar, setShowCalendar] = useState(false);
  const [locationError, setLocationError] = useState(null);
  const [newNotifications, setNewNotifications] = useState(0);

  useEffect(() => {
    const storedUser = JSON.parse(localStorage.getItem('user'));
    if (!storedUser) {
      navigate('/login');
    } else {
      setUser(storedUser);
      fetchVacationDays(storedUser.id);
      checkIfCheckedIn(storedUser.id);
      checkIfCheckedOut(storedUser.id);

      if (navigator.geolocation) {
        navigator.geolocation.getCurrentPosition(
            () => setLocationError(null),
            (err) => setLocationError(getLocationErrorMessage(err)),
            { enableHighAccuracy: true }
        );
      }
    }
  }, [navigate]);

  useEffect(() => {
    if (user) {
      const fetchNotifications = async () => {
        try {
          const response = await fetch(`${API_BASE_URL}/users/${user.id}/vacation-history`);
          if (!response.ok) throw new Error('Error al obtener notificaciones');
          const data = await response.json();
          const pendingCount = data.filter(r => r.status === 'pending').length;
          setNewNotifications(pendingCount);
        } catch (err) {
          console.error('Error al obtener notificaciones:', err.message);
        }
      };
      fetchNotifications();
    }
  }, [user]);

  const getLocationErrorMessage = (error) => {
    switch(error.code) {
      case error.PERMISSION_DENIED:
        return 'Permiso de ubicación denegado. Por favor habilita la geolocalización en tu navegador.';
      case error.POSITION_UNAVAILABLE:
        return 'La información de ubicación no está disponible.';
      case error.TIMEOUT:
        return 'La solicitud de ubicación tardó demasiado. Intenta nuevamente en un área con mejor señal.';
      default:
        return 'No se pudo obtener tu ubicación.';
    }
  };

  const checkIfCheckedIn = async (userId) => {
    try {
      const response = await fetch(`${API_BASE_URL}/users/${userId}/checkIn-status`);
      if (!response.ok) throw new Error('Error al verificar check-in');
      const data = await response.json();
      setHasCheckedIn(data.checkedIn);
    } catch (error) {
      console.error('Error al verificar check-in:', error);
    }
  };

  const checkIfCheckedOut = async (userId) => {
    try {
      const response = await fetch(`${API_BASE_URL}/users/${userId}/checkOut-status`);
      if (!response.ok) throw new Error('Error al verificar check-out');
      const data = await response.json();
      setHasCheckedOut(data.alreadyCheckedOut);
    } catch (error) {
      console.error('Error al verificar check-out:', error);
    }
  };

  const fetchVacationDays = async (userId) => {
    try {
      const response = await fetch(`${API_BASE_URL}/users/${userId}/vacation-days`);
      if (!response.ok) throw new Error('Error al obtener días de vacaciones');
      const data = await response.json();
      setVacationDays(data.vacation_days);
    } catch (error) {
      console.error('Error al obtener días de vacaciones:', error);
    }
  };

  const handleCheck = async (type) => {
    setLoading(true);
    setLocationError(null);

    if (!navigator.geolocation) {
      setLocationError('Tu navegador no soporta geolocalización.');
      setLoading(false);
      return;
    }

    try {
      const position = await new Promise((resolve, reject) => {
        navigator.geolocation.getCurrentPosition(
            resolve,
            reject,
            {
              enableHighAccuracy: true,
              timeout: 10000,
              maximumAge: 0
            }
        );
      });

      const { latitude, longitude } = position.coords;

      if (!latitude || !longitude) {
        throw new Error('Ubicación no válida');
      }

      const response = await fetch(`${API_BASE_URL}/users/${type === 'checkin' ? 'checkIn' : 'checkOut'}`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          userId: user.id,
          latitude,
          longitude
        }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || `Error en el ${type}`);
      }

      alert(`✅ ${type === 'checkin' ? 'Check-in' : 'Check-out'} registrado correctamente.`);

      setTimeout(() => {
        checkIfCheckedIn(user.id);
        checkIfCheckedOut(user.id);
      }, 500);

    } catch (error) {
      console.error(`Error en ${type}:`, error);
      setLocationError(getLocationErrorMessage(error) || error.message);
    } finally {
      setLoading(false);
    }
  };

  const handleLogout = () => {
    localStorage.removeItem('user');
    navigate('/login');
  };

  const handleDateChange = (date) => {
    const dateString = date.toISOString().split('T')[0];

    if (!selectedDates.includes(dateString) && selectedDates.length >= vacationDays) {
      alert(`❌ Ya has seleccionado el máximo de ${vacationDays} días permitidos.`);
      return;
    }

    if (selectedDates.includes(dateString)) {
      setSelectedDates(selectedDates.filter((d) => d !== dateString));
    } else {
      setSelectedDates([...selectedDates, dateString]);
    }
  };

  const handleVacationRequest = async () => {
    if (selectedDates.length === 0) {
      alert('❌ Debes seleccionar al menos un día de vacaciones.');
      return;
    }

    try {
      const response = await fetch(`${API_BASE_URL}/users/${user.id}/vacation-request`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ dates: selectedDates }),
      });

      if (!response.ok) {
        const errorData = await response.json();
        throw new Error(errorData.error || 'Error al solicitar vacaciones');
      }

      alert('✅ Vacaciones solicitadas correctamente. Espera la aprobación del administrador.');
      setShowCalendar(false);
      setSelectedDates([]);
      fetchVacationDays(user.id);
    } catch (error) {
      alert(`❌ ${error.message}`);
    }
  };

  const handleCancelSelection = () => {
    setSelectedDates([]);
  };

  const tileDisabled = ({ date, view }) => {
    if (view !== 'month') {
      return false;
    }
    return date < new Date(new Date().setHours(0, 0, 0, 0));
  };

  const tileClassName = ({ date, view }) => {
    if (view !== 'month') {
      return null;
    }
    const dateString = date.toISOString().split('T')[0];
    return selectedDates.includes(dateString) ? 'selected-date' : null;
  };

  return (
      <div className="flex flex-col items-center py-10 bg-gray-100 min-h-screen">
        {user && <h1 className="text-3xl font-bold text-gray-800">Bienvenido a tu panel, {user.name}</h1>}

        <p className="text-lg mt-4">
          Días de vacaciones disponibles: <strong>{vacationDays}</strong>
        </p>

        <div className="mt-6 flex flex-col items-center gap-2">
          {!hasCheckedIn && !hasCheckedOut && (
              <>
                <button
                    onClick={() => handleCheck('checkin')}
                    disabled={loading}
                    className={`px-4 py-2 rounded-md text-white font-medium transition-all ${
                        loading ? 'bg-gray-400 cursor-not-allowed' : 'bg-green-500 hover:bg-green-600'
                    }`}
                >
                  {loading ? 'Cargando...' : 'Check-in'}
                </button>
                {locationError && (
                    <div className="text-red-500 text-sm text-center max-w-xs">
                      {locationError}
                      <button
                          onClick={() => handleCheck('checkin')}
                          className="ml-2 text-blue-500 hover:underline"
                      >
                        Reintentar
                      </button>
                    </div>
                )}
              </>
          )}

          {hasCheckedIn && !hasCheckedOut && (
              <>
                <button
                    onClick={() => handleCheck('checkout')}
                    disabled={loading}
                    className={`px-4 py-2 rounded-md text-white font-medium transition-all ${
                        loading ? 'bg-gray-400 cursor-not-allowed' : 'bg-red-500 hover:bg-red-600'
                    }`}
                >
                  {loading ? 'Cargando...' : 'Check-out'}
                </button>
                {locationError && (
                    <div className="text-red-500 text-sm text-center max-w-xs">
                      {locationError}
                      <button
                          onClick={() => handleCheck('checkout')}
                          className="ml-2 text-blue-500 hover:underline"
                      >
                        Reintentar
                      </button>
                    </div>
                )}
              </>
          )}
        </div>

        <button
            onClick={() => setShowCalendar(!showCalendar)}
            disabled={vacationDays === 0}
            className={`mt-6 px-4 py-2 rounded-md text-white font-medium transition-all ${
                vacationDays > 0 ? 'bg-blue-500 hover:bg-blue-600' : 'bg-gray-400 cursor-not-allowed'
            }`}
        >
          Solicitar Vacaciones
        </button>

        {showCalendar && (
            <div className="mt-4 p-4 bg-white shadow-md rounded-md">
              <h2 className="text-lg font-bold mb-2">Selecciona los días de vacaciones</h2>
              <p className="mt-2 text-sm text-gray-700 text-center">
                Has seleccionado <strong>{selectedDates.length}</strong> {selectedDates.length === 1 ? 'día' : 'días'} de {vacationDays} disponibles
              </p>

              <Calendar
                  onClickDay={handleDateChange}
                  selectRange={false}
                  tileClassName={tileClassName}
                  tileDisabled={tileDisabled}
              />

              <div className="flex justify-center gap-4 mt-4">
                <button
                    onClick={handleCancelSelection}
                    className="px-4 py-2 bg-red-500 text-white rounded-md hover:bg-red-600 transition-all"
                >
                  Cancelar Selección
                </button>
                <button
                    onClick={handleVacationRequest}
                    className="px-4 py-2 bg-green-500 text-white rounded-md hover:bg-green-600 transition-all"
                >
                  Confirmar Selección
                </button>
              </div>
            </div>
        )}

        <button
            onClick={() => navigate('/employee/vacation-status')}
            className={`mt-4 px-4 py-2 rounded-md text-white font-medium transition-all relative ${
                newNotifications > 0 ? 'bg-purple-600 hover:bg-purple-700' : 'bg-blue-500 hover:bg-blue-600'
            }`}
        >
          Consultar Solicitudes
          {newNotifications > 0 && (
              <span className="absolute -top-2 -right-2 bg-red-500 text-white rounded-full w-5 h-5 flex items-center justify-center text-xs">
            {newNotifications}
          </span>
          )}
        </button>

        <button
            onClick={handleLogout}
            className="mt-8 px-4 py-2 bg-gray-700 text-white rounded-md hover:bg-gray-800 transition-all"
        >
          Cerrar Sesión
        </button>
      </div>
  );
};

export default EmployeeDashboard;
